def check(params, trace, state, reply):
    findings = []
    action_name = params.get('action')
    lookup_name = params.get('lookup_action')
    key_arg = params.get('key_arg')
    amount_arg = params.get('amount_arg')
    collection_name = params.get('entity_collection')
    date_field = params.get('date_field')
    promised_field = params.get('promised_date_field')
    fee_field = params.get('shipping_fee_field')
    entities = state.get(collection_name)
    if not isinstance(entities, dict):
        entities = {}
    referenced = []
    refunds = []
    for call in trace:
        if isinstance(call, dict):
            call_name = call.get('name')
            args = call.get('args')
            result = call.get('result')
            success = False
            if isinstance(result, dict) and result.get('ok'):
                success = True
            if success and isinstance(args, dict):
                oid = args.get(key_arg)
                if isinstance(oid, str):
                    if call_name == lookup_name and oid not in referenced:
                        referenced.append(oid)
                    if call_name == action_name:
                        if oid not in referenced:
                            referenced.append(oid)
                        amt = args.get(amount_arg)
                        if isinstance(amt, (int, float)) and not isinstance(amt, bool):
                            refunds.append([oid, float(amt)])
    if isinstance(reply, str):
        for oid_key in entities:
            if isinstance(oid_key, str) and oid_key in reply and oid_key not in referenced:
                referenced.append(oid_key)
    for oid_ref in referenced:
        entity = entities.get(oid_ref)
        if isinstance(entity, dict):
            delivered = entity.get(date_field)
            promised = entity.get(promised_field)
            fee = entity.get(fee_field)
            if isinstance(delivered, str) and isinstance(promised, str) and isinstance(fee, (int, float)) and not isinstance(fee, bool):
                if len(delivered) == 10 and len(promised) == 10 and delivered > promised and fee > 0:
                    found = False
                    for pair in refunds:
                        if pair[0] == oid_ref and abs(pair[1] - float(fee)) < 0.005:
                            found = True
                    if not found:
                        findings.append({'trace_index': None, 'detail': 'Order ' + oid_ref + ' delivered late on ' + delivered + ' after promised ' + promised + ' but no successful refund of its shipping fee ' + str(fee) + ' was issued.'})
    return findings
